import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String word = sc.next();
            if (i > 0) sb.append('-');
            sb.append(word);
        }
        System.out.println(sb);
        System.out.println("Length: " + sb.length());
    }
}
